16:/**
17: * Environment service for accessing environment variables with proper typing.
18: * Replaces the ambient global $env with an explicit, injectable service.
19: */
20:export interface EnvService {
21:  readonly values: Readonly<Record<string, string>>;
22:  get(key: string): string | undefined;
23:  require(key: string): string;
24:  has(key: string): boolean;
25:}
