27:/**
28: * Creates an environment service from base values and overlay layers.
29: * Later layers override earlier ones, but never override existing base values
30: * (launcher-owned names keep their launcher value).
31: */
32:export function createEnvService(opts: {
33:  base: Record<string, string | undefined>;
34:  layers: ReadonlyArray<Record<string, string>>;
35:}): EnvService {
36:  const merged: Record<string, string> = {};
37:  // Later layers override earlier ones, but never override existing base values
38:  // (launcher-owned names keep their launcher value).
39:  for (const layer of [...opts.layers].reverse()) {
40:    for (const [k, v] of Object.entries(layer) as [string, string][]) {
41:      if (!(k in merged) && opts.base[k] === undefined) merged[k] = v;
42:    }
43:  }
44:  for (const [k, v] of Object.entries(opts.base) as [string, string | undefined][]) {
45:    if (v !== undefined) merged[k] = v;
46:  }
47:  return Object.freeze({
48:    values: Object.freeze(merged),
49:    get: (k: string) => merged[k],
50:    require: (k: string) => {
51:      const v = merged[k];
52:      if (v === undefined) throw new Error(`Missing required env: ${k}`);
53:      return v;
54:    },
55:    has: (k: string) => k in merged,
56:  });
57:}
