98:/**
99: * The only names that are genuinely unsafe to forward to a native `execve`
100: * spawn: empty, containing `=` (would corrupt the `KEY=VALUE` framing) or
101: * NUL (terminates the C string mid-entry). Windows ships standard variables
102: * whose names contain parentheses (e.g. `ProgramFiles(x86)`, `CommonProgramFiles(x86)`)
103: * — those MUST survive the scrub so downstream resolvers (Git Bash discovery
104: * in `procmgr.ts`, etc.) can still read them.
105: */
106:export function isSafeEnvName(name: string): boolean {
107:	return name.length > 0 && !name.includes("=") && !name.includes("\0");
108:}
