165:export function filterProcessEnv(env: Record<string, string | undefined>): Record<string, string> {
166:	const result: Record<string, string> = {};
167:	for (const key in env) {
168:		const value = env[key];
169:		if (
170:			!isSafeEnvName(key) ||
171:			isDangerousEnvName(key) ||
172:			isMacosMallocStackLoggingEnvName(key) ||
173:			value === undefined ||
174:			!isSafeEnvValue(value)
175:		) {
176:			continue;
177:		}
178:		result[key] = value;
179:	}
180:	return result;
