206:export function stripGitRepoLocationEnv(
207:	env: Record<string, string>,
208:	platform: NodeJS.Platform = process.platform,
209:): void {
210:	if (platform !== "win32") {
211:		for (const name of GIT_REPO_LOCATION_ENV_NAMES) {
212:			delete env[name];
213:		}
214:		return;
215:	}
216:	const folded = new Set<string>(GIT_REPO_LOCATION_ENV_NAMES.map(name => name.toLowerCase()));
217:	for (const key of Object.keys(env)) {
218:		if (folded.has(key.toLowerCase())) {
219:			delete env[key];
