307:	const projectEnv = parseEnvFile(path.join(cwd, ".env"));
308:	const launchNodeEnv = runtimeLaunchEnvValues ? runtimeLaunchEnvValues.get("NODE_ENV") : env.NODE_ENV;
309:	const nodeEnvName = `.env.${launchNodeEnv || "development"}`;
310:	const modeEnv = parseEnvFile(path.join(cwd, nodeEnvName));
311:	const localEnv = parseEnvFile(path.join(cwd, ".env.local"));
312:	const modeLocalEnv = parseEnvFile(path.join(cwd, `${nodeEnvName}.local`));
313:	const launchEnv = { ...projectEnv, ...modeEnv, ...localEnv, ...modeLocalEnv };
314:	const expandedLaunchEnv = {
