321:	let expandedFallbackLaunchEnv: Record<string, string> | undefined;
322:	if (!runtimeLaunchEnvValues && nodeEnvName !== ".env.development") {
323:		const fallbackModeEnv = parseEnvFile(path.join(cwd, ".env.development"));
324:		const fallbackModeLocalEnv = parseEnvFile(path.join(cwd, ".env.development.local"));
325:		const candidate = { ...projectEnv, ...fallbackModeEnv, ...localEnv, ...fallbackModeLocalEnv };
326:		const expandedCandidate = {
327:			...expandDotenvValues(projectEnv, result),
328:			...expandDotenvValues(fallbackModeEnv, result),
329:			...expandDotenvValues(localEnv, result),
330:			...expandDotenvValues(fallbackModeLocalEnv, result),
331:		};
