407:/**
408: * Parses a complete .env file with the runtime's dotenv grammar, then retains
409: * only shell-identifier names and spawn-safe values before mirroring valid
410: * `OMP_` variables to their `PI_` aliases.
411: */
412:const __parseEnvFileCache = new Map<string, { mtime: number; data: Record<string, string> }>();
413:
414:export function parseEnvFile(filePath: string): Record<string, string> {
415:	// Memoize on (path, mtime). filterChildShellEnvInternal reads 4 dotenv files per
416:	// child-shell spawn; without this, every subprocess pays 4 synchronous reads.
417:	let mtime = 0;
418:	try {
419:		mtime = statSync(filePath).mtimeMs;
420:	} catch {
421:		/* missing -> empty */
422:	}
423:	const cached = __parseEnvFileCache.get(filePath);
424:	if (cached && cached.mtime === mtime) return cached.data;
425:	const result: Record<string, string> = {};
426:	try {
427:		const parsed = parseEnv(fs.readFileSync(filePath, "utf-8"));
428:		for (const key in parsed) {
429:			const value = parsed[key];
430:			if (
431:				value !== undefined &&
432:				isValidEnvName(key) &&
433:				!isDangerousEnvName(key) &&
434:				!isDotenvForbiddenName(key) &&
435:				isSafeEnvValue(value)
436:			)
437:				result[key] = value;
438:		}
439:	} catch {
440:		// File doesn't exist or can't be read - return empty result
441:	}
442:
443:	// OMP_ overrides PI_
444:	for (const k in result) {
445:		if (k.startsWith("OMP_")) {
446:			result[`PI_${k.slice(4)}`] = result[k];
447:		}
448:	}
449:
450:	__parseEnvFileCache.set(filePath, { mtime, data: result });
451:	return result;
452:}
