492:/**
493: * Read an environment variable by its EXACT, case-sensitive name.
494: *
495: * `process.env` / `Bun.env` lookups are case-insensitive on Windows (Node backs
496: * them with `uv_os_getenv`, Bun with a `CaseInsensitiveASCIIStringArrayHashMap`),
497: * so a lowercase literal like `public` silently resolves to a differently-cased
498: * system variable — Windows ships `PUBLIC=C:\Users\Public`. Enumerated keys are
499: * the only signal that preserves the real casing, so this trusts the lookup only
500: * when a key with identical casing is actually present. On POSIX (case-sensitive
501: * env) it is equivalent to a direct lookup.
502: *
503: * Use this instead of `process.env[name] ?? literal` wherever `name` may be a
504: * user-supplied literal (e.g. a stored API key) rather than a genuine env-var
505: * reference — otherwise the literal gets hijacked by a same-named system var.
506: *
507: * @param name - Environment variable name to look up.
508: * @param env - Environment source; defaults to `process.env`.
509: */
510:export function $envExact(name: string, env: Record<string, string | undefined> = process.env): string | undefined {
511:	const value = env[name];
512:	if (value === undefined) return undefined;
513:	// Enumeration preserves real key casing on Windows, unlike the getter; the
514:	// value is trusted only when an exact-case entry actually exists.
515:	for (const key in env) {
516:		if (key === name) return value;
517:	}
518:	return undefined;
519:}
