521:/**
522: * Parses a positive decimal integer from `$env[name]`.
523: * Empty, invalid, NaN, zero, or negative values return `defaultValue`.
524: */
525:export function $envpos(name: string, defaultValue: number): number {
526:	const raw = $env[name];
527:	if (!raw) return defaultValue;
528:	const parsed = Number.parseInt(raw, 10);
529:	if (Number.isNaN(parsed) || parsed <= 0) return defaultValue;
530:	return parsed;
